import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03001Controller {
  @Post('/approval-documents/:approvalDocumentId/submit')
  @HttpCode(200)
  async submitApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['approvalDocumentId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    const lines = data['approvalLines'];
    if (!Array.isArray(lines) || lines.length === 0) {
      throw new ApiError(422, 'APPROVAL_LINE_REQUIRED', '결재선을 지정해 주세요.');
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus", drafter_department_id AS "departmentId" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '기안문을 찾을 수 없습니다.');
      }
      const doc = docs[0];
      // 전환표: 기안 상태에서만 상신할 수 있다.
      if (doc.approvalStatus !== '기안') {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_ALREADY_SUBMITTED', '이미 상신된 문서입니다.');
      }
      // 가정: 기안부서 규칙을 우선하고 없으면 전사 공통 규칙으로 채번한다. 단위별 순번 초기화는 하지 않는다.
      const rules = await db.query(
        "SELECT numbering_rule_id AS \"ruleId\" FROM numbering_rule WHERE target_type = 'DOCUMENT' AND (department_id = CAST(:departmentId AS bigint) OR department_id IS NULL) ORDER BY (department_id IS NULL) ASC, numbering_rule_id ASC LIMIT 1 FOR UPDATE",
        { departmentId: String(doc.departmentId) },
      );
      if (rules.length === 0) {
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '문서번호 채번 규칙이 없어 상신하지 못했습니다.');
      }
      const seqRows = await db.query(
        'UPDATE numbering_rule SET current_sequence = COALESCE(current_sequence, 0) + 1, updated_at = now() WHERE numbering_rule_id = CAST(:ruleId AS bigint) RETURNING current_sequence AS "seq", prefix AS "prefix", digits AS "digits"',
        { ruleId: String(rules[0].ruleId) },
      );
      const rule = seqRows[0];
      const documentNumber = (rule.prefix ? rule.prefix + '-' : '') + String(rule.seq).padStart(Number(rule.digits), '0');
      const rows = await db.query(
        "UPDATE approval_document SET document_number = :documentNumber, approval_status = '결재대기', submitted_at = now(), updated_at = now() WHERE approval_document_id = CAST(:id AS bigint) RETURNING approval_document_id AS \"approvalDocumentId\", approval_status AS \"approvalStatus\", submitted_at AS \"submittedAt\"",
        { documentNumber, id: idText },
      );
      return rows[0];
    });
  }
}

