import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  DateInput,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Select,
  TextInput,
  NumberInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03001Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [submitting, setSubmitting] = useState<Row | null>(null);
  const [formId, setFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [bizType, setBizType] = useState('');
  const [bizId, setBizId] = useState<number | string>('');
  const [urgent, setUrgent] = useState('false');
  const [secret, setSecret] = useState('false');
  const [approvers, setApprovers] = useState<(number | string)[]>(['']);

  const draftCount = rows.filter((r) => r.approvalStatus === '기안').length;
  const submittedCount = rows.length - draftCount;

  function openCreate() {
    setFormId('');
    setTitle('');
    setBody('');
    setBizType('');
    setBizId('');
    setUrgent('false');
    setSecret('false');
    setCreating(true);
  }

  function openSubmit(row: Row) {
    setApprovers(['']);
    setSubmitting(row);
  }

  async function saveDraft() {
    if (formId === '' || title.trim() === '' || bizType.trim() === '' || bizId === '') {
      throw new Error('결재양식, 문서 제목, 연계 업무 유형, 연계 업무 식별자는 필수입니다.');
    }
    const res = await call('POST', '/approval-documents', role, {
      approvalFormId: formId,
      title,
      body,
      linkedBusinessType: bizType,
      linkedBusinessId: bizId,
      isUrgent: urgent === 'true',
      isSecret: secret === 'true',
    });
    setRows([{ ...res, title, approvalFormId: formId }, ...rows]);
    setCreating(false);
    notify('기안문을 임시저장했습니다.');
  }

  async function submitDoc() {
    if (!submitting) return;
    const chosen = approvers.filter((a) => a !== '');
    if (chosen.length === 0) {
      throw new Error('결재선을 지정해 주세요.');
    }
    const res = await call('POST', `/approval-documents/${submitting.approvalDocumentId}/submit`, role, {
      approvalLines: chosen.map((a) => ({ approverId: a })),
    });
    setRows(rows.map((r) => (r.approvalDocumentId === submitting.approvalDocumentId ? { ...r, ...res } : r)));
    setSubmitting(null);
    notify('상신했습니다.');
  }

  function setApproverAt(index: number, value: number | string) {
    setApprovers(approvers.map((a, i) => (i === index ? value : a)));
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['임시저장 기안', draftCount],
            ['상신 완료', submittedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>기안문</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openCreate}>기안문 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 작성한 기안문이 없습니다."
          columns={[
            { key: 'approvalDocumentId', label: '결재문서 ID' },
            { key: 'title', label: '문서 제목' },
            {
              key: 'approvalFormId',
              label: '결재양식',
              render: (r) => <RefName table="approval_form" role={role} value={r.approvalFormId} />,
            },
            { key: 'documentNumber', label: '문서번호' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r.submittedAt} time /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.approvalStatus === '기안' ? (
                  <button type="button" onClick={() => openSubmit(r)}>상신</button>
                ) : null,
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title="기안문 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={saveDraft} submit="임시저장">
            <Field label="결재양식" required>
              <LookupSelect table="approval_form" role={role} value={formId} onChange={setFormId} />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="연계 업무 유형" required>
              <TextInput value={bizType} onChange={setBizType} />
            </Field>
            <Field label="연계 업무 식별자" required>
              <NumberInput value={bizId} onChange={setBizId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={urgent} onChange={setUrgent} options={[['false', '아니오'], ['true', '예']]} placeholder="선택" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={secret} onChange={setSecret} options={[['false', '아니오'], ['true', '예']]} placeholder="선택" />
            </Field>
          </Form>
        </Drawer>
      )}
      {submitting && (
        <Drawer title="기안문 상신" onClose={() => setSubmitting(null)}>
          <Form onSubmit={submitDoc} submit="상신">
            <Field label="문서 제목" wide>
              <span>{String(submitting.title ?? '')}</span>
            </Field>
            {approvers.map((a, i) => (
              <Field key={i} label={`결재선 결재자 ${i + 1}`} required wide>
                <LookupSelect table="employee" role={role} value={a} onChange={(v) => setApproverAt(i, v)} />
              </Field>
            ))}
            <button type="button" onClick={() => setApprovers([...approvers, ''])}>결재자 추가</button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
